const html = String($input.first().json.data || '');
const blocks = html.split(/class="products-i[^"]*"/).slice(1);
const elanlar = [];
for (const block of blocks) {
  const ad = (block.match(/products-i__name">([^<]*)/) || [])[1];
  if (!ad || !ad.trim()) continue;
  const qiymet = ((block.match(/products-i__price">([^<]*)/) || [])[1] || '').trim();
  const atributlar = ((block.match(/products-i__attributes">([^<]*)/) || [])[1] || '').trim();
  const yer_vaxt = ((block.match(/products-i__datetime">([^<]*)/) || [])[1] || '').trim();
  const href = ((block.match(/products-i__link" href="([^"]*)/) || [])[1] || '').trim();
  elanlar.push({
    ad: ad.trim(),
    qiymet,
    atributlar,
    yer_vaxt,
    seher: yer_vaxt.split(',')[0].trim(),
    link: href ? (href.startsWith('http') ? href : 'https://turbo.az' + href) : '',
  });
}
const reqemler = elanlar.map(e => Number(String(e.qiymet).replace(/[^0-9]/g, ''))).filter(n => n > 0);
const ortalama = reqemler.length ? Math.round(reqemler.reduce((a, b) => a + b, 0) / reqemler.length) : 0;
return [{
  json: {
    say: elanlar.length,
    ortalama,
    elanlar,
  }
}];

const item = $input.first().json;
const text = JSON.stringify(item.elanlar || [], null, 2);
return [{ json: item, binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'elanlar.json' } } }];
